<?php
namespace App\Http\Controllers\Management;use App\Http\Controllers\Controller;use App\Models\SystemSetting;use Illuminate\Http\Request;
class SettingsController extends Controller{public function index(Request $r){abort_unless($r->user()->isManager(),403);return view('management.settings',['settings'=>SystemSetting::where('property_id',$r->user()->property_id)->orderBy('group')->orderBy('key')->get()]);}public function store(Request $r){abort_unless($r->user()->isManager(),403);$d=$r->validate(['group'=>'required|string|max:50','key'=>'required|string|max:100','value'=>'nullable|string','type'=>'required|in:string,number,boolean,json','is_secret'=>'nullable|boolean']);SystemSetting::updateOrCreate(['property_id'=>$r->user()->property_id,'key'=>$d['key']],$d);return back()->with('success','Setting saved.');}}
